fn abs_f32(x: f32) -> f32 {
    if x < 0.0 { -x } else { x }
}

fn assert_near(a: f32, b: f32, eps: f32, msg: str) with IO, Panic {
    if abs_f32(a - b) > eps {
        println("FAIL: " ++ msg)
        panic("assertion failed")
    }
}

fn assert_true(cond: bool, msg: str) with IO, Panic {
    if !cond {
        println("FAIL: " ++ msg)
        panic("assertion failed")
    }
}

