    if moments_fib[6 as usize] != 8448 { fib_ok = 0 }

    // 2*K_7: 7x7 matrix with off-diagonal 2. moments trace(A^k) k=1..4.
    var B = [0; 49]
    var bi = 0
    while bi < 7 {
        var bj = 0
        while bj < 7 {
            if bi != bj { B[(bi * 7 + bj) as usize] = 2 }
            bj = bj + 1
        }
        bi = bi + 1
    }
    var Q = [0; 49]
